import{_ as l,o as i,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2015-APR-23 -- Ceph Tech Talks: Calamari","description":"","frontmatter":{"title":"2015-APR-23 -- Ceph Tech Talks: Calamari","date":"2015-05-04T00:00:00.000Z","updated":"2015-05-04T00:00:00.000Z","tags":["Ceph","Calamari","Ramona","Storage Management","Ceph Monitoring"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/2015-APR-23_--_Ceph_Tech_Talks_-_Calamari.md","filePath":"posts/2015/2015-APR-23_--_Ceph_Tech_Talks_-_Calamari.md","lastUpdated":1780459816000}'),r={name:"posts/2015/2015-APR-23_--_Ceph_Tech_Talks_-_Calamari.md"};function o(p,a,_,s,n,m){return i(),e("div",null,[...a[0]||(a[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次Ceph技术讲座主要围绕Calamari和Romana两个项目展开，这两个项目分别是Ceph的管理API和图形用户界面（GUI）。</p><p><strong>主要内容</strong>：</p><ol><li><p><strong>Calamari和Romana简介</strong>：</p><ul><li>Calamari作为API，提供所有信息，支持用户界面操作。</li><li>Romana作为管理监控仪表板，提供Ceph集群的概览，包括集群状态、OSD状态、集群管理功能等。</li></ul></li><li><p><strong>Calamari后端架构</strong>：</p><ul><li>架构包括仪表板、Django REST框架应用、Thulu服务（缓存层）、数据库和Graphite数据存储。</li><li>使用Salt和ZeroMQ消息总线与Ceph集群上的代理进行通信，收集集群状态信息。</li></ul></li><li><p><strong>Calamari未来发展</strong>：</p><ul><li>计划增加对硬件状态的监控，如硬盘健康状态、热插拔支持等。</li><li>考虑增加更多管理功能，如集群部署、OSD管理等。</li><li>欢迎社区反馈和合作。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>开发并测试硬件监控模块。</li><li>根据社区反馈，确定API扩展的具体功能和优先级。</li><li>加强与社区的沟通，鼓励社区成员参与Calamari的开发和测试。</li></ul></li><li><p><strong>其他讨论</strong>：</p><ul><li>讨论了Calamari的包装和部署问题，欢迎社区帮助改进。</li><li>提到了一些需要上游贡献的组件，如Diamond，希望社区能参与讨论和贡献。</li></ul></li></ol><p>本次讲座详细介绍了Calamari和Romana的架构、功能以及未来的发展方向，为Ceph的用户和开发者提供了宝贵的参考信息。</p>',5)])])}const c=l(r,[["render",o]]);export{h as __pageData,c as default};
